import { test } from 'node:test';
import assert from 'node:assert';
import {
  COMMAND_DIRS,
  TASKS_DIR,
  TASK_FILE_PREFIX,
  TASK_FILE_EXT,
  TASK_ID_PAD_WIDTH,
  DEFAULT_FILE_LOCK_TIMEOUT_MS,
  ARCHIVE_DIR,
  ARCHIVE_TASKS_DIR,
  ARCHIVE_TASK_FILE,
} from './index.ts';


test('COMMAND_DIRS.opencode should remain unchanged', () => {
  assert.strictEqual(COMMAND_DIRS.opencode, '.opencode/command');
});


test('COMMAND_DIRS.default should not contain any old project names', () => {
  assert.ok(!COMMAND_DIRS.default.includes('hyper-designer'), 'should not contain hyper-designer');
  assert.ok(!COMMAND_DIRS.default.includes('neo-designer'), 'should not contain neo-designer');
  assert.ok(!COMMAND_DIRS.default.includes('hd'), 'should not contain hd');
  assert.ok(!COMMAND_DIRS.default.includes('hyper'), 'should not contain hyper');
  assert.ok(!COMMAND_DIRS.default.includes('neo'), 'should not contain neo');
});


test('other constants remain unchanged after rename', () => {
  assert.strictEqual(TASKS_DIR, 'tasks');
  assert.strictEqual(TASK_FILE_PREFIX, 'task-');
  assert.strictEqual(TASK_FILE_EXT, '.json');
  assert.strictEqual(TASK_ID_PAD_WIDTH, 4);
  assert.strictEqual(DEFAULT_FILE_LOCK_TIMEOUT_MS, 5000);
  assert.strictEqual(ARCHIVE_DIR, 'archive');
  assert.strictEqual(ARCHIVE_TASKS_DIR, 'tasks');
  assert.strictEqual(ARCHIVE_TASK_FILE, 'task.json');
});
